import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Mascot } from "@/components/ui/mascot"
import type { Conversation } from "@/components/blocks/chat-app/components/chat-app-data"

export function ChatAppFace({ conversation, size = 36, name }: { conversation: Pick<Conversation, "id" | "kind" | "name">; size?: number; name?: string }) {
  if (conversation.kind === "assistant") {
    const draw = Math.round(size * 1.25)
    return <Mascot pose="idle" size={draw} seed={`${conversation.id}-face`} style={{ margin: -(draw - size) / 2 }} />
  }
  return (
    <Avatar size={size > 36 ? "lg" : "default"} seed={`${conversation.id}-${name ?? ""}`}>
      <AvatarFallback name={name ?? conversation.name} />
    </Avatar>
  )
}

"use client"

import * as React from "react"

import type { ChatFile, ChatPart, Conversation } from "@/components/blocks/chat-app/components/chat-app-data"

export type ChatStatus = "ready" | "submitted" | "streaming"

type Step = { wait: number; apply: (parts: ChatPart[]) => ChatPart[] }

function replySteps(script: ChatPart[]): Step[] {
  return script.flatMap((part): Step[] =>
    part.kind === "text"
      ? part.text.split(" ").map((word, k) => ({
          wait: 85,
          apply: (parts) => {
            const last = parts[parts.length - 1]
            return k > 0 && last?.kind === "text" ? [...parts.slice(0, -1), { kind: "text", text: `${last.text} ${word}` }] : [...parts, { kind: "text", text: word }]
          },
        }))
      : [{ wait: 700, apply: (parts) => [...parts, part] }]
  )
}

export function useChatApp(initial: Conversation[], firstId: string, onSend?: (conversationId: string, text: string, files: ChatFile[]) => void) {
  const [conversations, setConversations] = React.useState(initial)
  const [activeId, setActiveId] = React.useState(firstId)
  const [stream, setStream] = React.useState<{ id: string; phase: "submitted" | "streaming" } | null>(null)
  const [announce, setAnnounce] = React.useState("")
  const timers = React.useRef<number[]>([])
  const counter = React.useRef(0)

  const clear = React.useCallback(() => {
    timers.current.forEach((t) => window.clearTimeout(t))
    timers.current = []
  }, [])
  React.useEffect(() => clear, [clear])

  const stop = React.useCallback(() => {
    clear()
    setStream(null)
  }, [clear])

  const select = React.useCallback(
    (id: string) => {
      if (id === activeId) return
      stop()
      setActiveId(id)
      setAnnounce("")
      setConversations((all) => all.map((c) => (c.id === id && c.unread ? { ...c, unread: 0 } : c)))
    },
    [stop, activeId]
  )

  const send = React.useCallback(
    (text: string, files: ChatFile[] = []) => {
      const convo = conversations.find((c) => c.id === activeId)
      if (!convo) return
      onSend?.(convo.id, text, files)
      const n = counter.current++
      const mine = `me-${n}`
      const theirs = `re-${n}`
      const who = convo.replyFrom
      setConversations((all) =>
        all.map((c) =>
          c.id === activeId
            ? { ...c, time: "now", turns: [...c.turns, { id: mine, from: "me", time: "now", parts: [{ kind: "text", text: text || "(the files)" }], files: files.length ? files : undefined }] }
            : c
        )
      )
      setStream({ id: activeId, phase: "submitted" })
      setAnnounce("")
      const steps = replySteps(convo.reply)
      let at = 700
      timers.current.push(
        window.setTimeout(() => {
          setStream({ id: activeId, phase: "streaming" })
          setConversations((all) => all.map((c) => (c.id === activeId ? { ...c, turns: [...c.turns, { id: theirs, from: "them", who, time: "now", parts: [] }] } : c)))
        }, at)
      )
      steps.forEach((step, i) => {
        at += step.wait
        timers.current.push(
          window.setTimeout(() => {
            setConversations((all) =>
              all.map((c) => (c.id === activeId ? { ...c, turns: c.turns.map((t) => (t.id === theirs ? { ...t, parts: step.apply(t.parts) } : t)) } : c))
            )
            if (i === steps.length - 1) {
              setStream(null)
              setAnnounce(`${convo.name} replied`)
            }
          }, at)
        )
      })
    },
    [conversations, activeId, onSend]
  )

  const status: ChatStatus = stream && stream.id === activeId ? stream.phase : "ready"
  return { conversations, activeId, active: conversations.find((c) => c.id === activeId), status, announce, select, send, stop }
}

"use client"

import * as React from "react"

import {
  Attachment,
  AttachmentAction,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentTitle,
} from "@/components/ui/attachment"
import { Bubble, BubbleContent } from "@/components/ui/bubble"
import { Button } from "@/components/ui/button"
import { CodeBlock } from "@/components/ui/code-block"
import { Icon } from "@/components/ui/icon"
import { Marker, MarkerContent } from "@/components/ui/marker"
import { Message, MessageAvatar, MessageContent, MessageHeader, MessageText } from "@/components/ui/message"
import {
  MessageScroller,
  MessageScrollerButton,
  MessageScrollerContent,
  MessageScrollerItem,
  MessageScrollerProvider,
  MessageScrollerViewport,
} from "@/components/ui/message-scroller"
import { Paper } from "@/components/ui/paper"
import {
  PromptInput,
  PromptInputAttachments,
  PromptInputBody,
  PromptInputButton,
  PromptInputFooter,
  PromptInputHint,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputTools,
  usePromptInput,
} from "@/components/ui/prompt-input"
import { TypingIndicator } from "@/components/ui/typing-indicator"
import { ChatAppFace } from "@/components/blocks/chat-app/components/chat-app-face"
import type { ChatFile, ChatPart, ChatTurn, Conversation } from "@/components/blocks/chat-app/components/chat-app-data"
import type { ChatStatus } from "@/components/blocks/chat-app/components/chat-app-state"
import { cn } from "@/lib/utils"

function FileChip({ file, children }: { file: ChatFile; children?: React.ReactNode }) {
  return (
    <Attachment size="sm" seed={file.name}>
      <AttachmentMedia>
        <Icon name="file-text" />
      </AttachmentMedia>
      <AttachmentContent>
        <AttachmentTitle>{file.name}</AttachmentTitle>
        <AttachmentDescription>{file.size}</AttachmentDescription>
      </AttachmentContent>
      {children}
    </Attachment>
  )
}

function ToolNote({ title, result }: { title: string; result: string }) {
  return (
    <Bubble shape="note" variant="muted" className="max-w-full">
      <BubbleContent className="flex items-center gap-2 px-4 py-2 font-type text-sm leading-snug" paper={{ tilt: -0.7, curl: false }}>
        <Icon name="terminal" size={14} />
        <span>{title}</span>
        <span className="font-bold text-green">{result}</span>
      </BubbleContent>
    </Bubble>
  )
}

function Parts({ turn, conversation, live }: { turn: ChatTurn; conversation: Conversation; live: boolean }) {
  const prose = conversation.kind === "assistant"
  return (
    <>
      {turn.parts.map((p: ChatPart, i) => {
        if (p.kind === "tool") return <ToolNote key={i} title={p.title} result={p.result} />
        if (p.kind === "code") return <CodeBlock key={i} diff language="ts" filename={p.filename} code={p.code} seed={`${turn.id}-${i}`} className="mt-1" />
        return (
          <Bubble key={i} variant={prose ? "ghost" : "muted"} className="max-w-full">
            <BubbleContent seed={`${turn.id}-${i}`}>
              <MessageText streaming={live && i === turn.parts.length - 1} seed={`${turn.id}-${i}`}>
                {p.text}
              </MessageText>
            </BubbleContent>
          </Bubble>
        )
      })}
    </>
  )
}

function TurnView({ turn, conversation, live }: { turn: ChatTurn; conversation: Conversation; live: boolean }) {
  if (turn.from === "me") {
    const first = turn.parts[0]
    return (
      <Message align="end">
        <MessageContent>
          <MessageHeader className="justify-end">you · {turn.time}</MessageHeader>
          <Bubble variant="outline" pen="you">
            <BubbleContent seed={turn.id}>{first?.kind === "text" ? first.text : ""}</BubbleContent>
          </Bubble>
          {turn.files ? (
            <div className="flex flex-wrap justify-end gap-3 pt-2">
              {turn.files.map((f) => (
                <FileChip key={f.name} file={f} />
              ))}
            </div>
          ) : null}
        </MessageContent>
      </Message>
    )
  }
  const name = turn.who ?? conversation.name
  return (
    <Message>
      <MessageAvatar>
        <ChatAppFace conversation={conversation} name={name} size={conversation.kind === "assistant" ? 36 : 32} />
      </MessageAvatar>
      <MessageContent>
        <MessageHeader>
          {name} · {turn.time}
        </MessageHeader>
        <Parts turn={turn} conversation={conversation} live={live} />
        {turn.files ? (
          <div className="flex flex-wrap gap-3 pt-2">
            {turn.files.map((f) => (
              <FileChip key={f.name} file={f} />
            ))}
          </div>
        ) : null}
      </MessageContent>
    </Message>
  )
}

function RemoveFile({ name, onRemove }: { name: string; onRemove: () => void }) {
  const { focus } = usePromptInput()
  return (
    <AttachmentAction
      aria-label={`Remove ${name}`}
      onClick={() => {
        onRemove()
        focus()
      }}
    >
      <Icon name="x" />
    </AttachmentAction>
  )
}

type Props = {
  conversation: Conversation
  status: ChatStatus
  announce: string
  onSend: (text: string, files: ChatFile[]) => void
  onStop: () => void
  onBack: () => void
  className?: string
}

export function ChatAppThread({ conversation, status, announce, onSend, onStop, onBack, className }: Props) {
  const [files, setFiles] = React.useState<ChatFile[]>([])
  const heading = React.useId()
  const busy = status !== "ready"
  const attachable = conversation.attachable

  return (
    <Paper
      as="section"
      stock="card"
      tilt={0.25}
      tape="top"
      tapeKind="washi-dots"
      seed="chat-thread"
      aria-labelledby={heading}
      data-slot="chat-app-thread"
      className={cn("flex min-h-0 flex-col pt-5 pb-3", className)}
    >
      <header className="flex items-center gap-3 px-4 pb-2 sm:px-6">
        <Button variant="ghost" size="icon-sm" className="@3xl/chat:hidden" onClick={onBack} aria-label="Back to chats">
          <Icon name="arrow-left" className="rtl:-scale-x-100" />
        </Button>
        <ChatAppFace conversation={conversation} size={40} />
        <div className="min-w-0">
          <h2 id={heading} tabIndex={-1} className="truncate font-script text-[1.7rem] leading-none font-semibold outline-offset-4 focus-visible:outline-2 focus-visible:outline-focus">
            {conversation.name}
          </h2>
          <p className="truncate text-sm text-muted-foreground">{conversation.subtitle}</p>
        </div>
      </header>

      <MessageScrollerProvider autoScroll defaultScrollPosition="end">
        <MessageScroller className="min-h-0 flex-1">
          <MessageScrollerViewport aria-label={`Messages with ${conversation.name}`}>
            <MessageScrollerContent aria-live={busy ? "off" : undefined}>
              <Marker variant="separator">
                <MarkerContent>Today</MarkerContent>
              </Marker>
              {conversation.turns.map((t, i) => (
                <MessageScrollerItem key={t.id} messageId={t.id} scrollAnchor={t.from === "me"}>
                  <TurnView turn={t} conversation={conversation} live={status === "streaming" && i === conversation.turns.length - 1 && t.from === "them"} />
                </MessageScrollerItem>
              ))}
              {status === "submitted" ? (
                <MessageScrollerItem messageId="typing">
                  <Message>
                    <MessageContent>
                      <Bubble variant="muted">
                        <BubbleContent seed="typing">
                          <TypingIndicator variant={conversation.kind === "assistant" ? "squiggle" : "dots"} label={`${conversation.replyFrom ?? conversation.name} is writing a reply`} seed="typing" />
                        </BubbleContent>
                      </Bubble>
                    </MessageContent>
                  </Message>
                </MessageScrollerItem>
              ) : null}
            </MessageScrollerContent>
          </MessageScrollerViewport>
          <MessageScrollerButton />
        </MessageScroller>
      </MessageScrollerProvider>

      <p role="status" className="sr-only">
        {announce}
      </p>

      <div className="px-3 pt-1">
        <PromptInput
          seed="chat-composer"
          status={status}
          allowEmpty={files.length > 0}
          onStop={onStop}
          onSubmit={(text) => {
            onSend(text, files)
            setFiles([])
          }}
        >
          <PromptInputAttachments>
            {files.map((f) => (
              <FileChip key={f.name} file={f}>
                <AttachmentActions>
                  <RemoveFile name={f.name} onRemove={() => setFiles((all) => all.filter((x) => x.name !== f.name))} />
                </AttachmentActions>
              </FileChip>
            ))}
          </PromptInputAttachments>
          <PromptInputBody>
            <PromptInputTextarea aria-label={`Message ${conversation.name}`} placeholder="write something kind" />
          </PromptInputBody>
          <PromptInputFooter>
            <PromptInputTools>
              <PromptInputButton
                size="icon-sm"
                aria-label="Attach a file"
                disabled={files.length >= attachable.length}
                onClick={() => setFiles((all) => (all.length < attachable.length ? [...all, attachable[all.length]] : all))}
              >
                <Icon name="paperclip" />
              </PromptInputButton>
            </PromptInputTools>
            <PromptInputHint className="@max-3xl/chat:sr-only">{busy ? "Press stop to interrupt" : "Enter to send, Shift+Enter for a new line"}</PromptInputHint>
            <PromptInputSubmit />
          </PromptInputFooter>
        </PromptInput>
      </div>
    </Paper>
  )
}

"use client"

import * as React from "react"

import { ChatAppConversationList } from "@/components/blocks/chat-app/components/chat-app-conversation-list"
import { CONVERSATIONS, type ChatFile, type Conversation } from "@/components/blocks/chat-app/components/chat-app-data"
import { useChatApp } from "@/components/blocks/chat-app/components/chat-app-state"
import { ChatAppThread } from "@/components/blocks/chat-app/components/chat-app-thread"
import { cn } from "@/lib/utils"

type Props = {
  className?: string
  conversations?: Conversation[]
  onSend?: (conversationId: string, text: string, files: ChatFile[]) => void
}

export default function ChatApp({ className, conversations = CONVERSATIONS, onSend }: Props) {
  const chat = useChatApp(conversations, conversations[0]?.id ?? "", onSend)
  const [view, setView] = React.useState<"list" | "thread">("list")
  const grid = React.useRef<HTMLDivElement>(null)
  const shown = React.useRef(view)
  React.useEffect(() => {
    if (shown.current === view) return
    shown.current = view
    const gone = grid.current?.querySelector<HTMLElement>(view === "thread" ? "[data-slot=chat-app-list]" : "[data-slot=chat-app-thread]")
    if (!gone || getComputedStyle(gone).display !== "none") return
    const pane = view === "thread" ? "[data-slot=chat-app-thread]" : "[data-slot=chat-app-list]"
    const target = (view === "list" ? grid.current?.querySelector<HTMLElement>(`${pane} [aria-current=true]`) : null) ?? grid.current?.querySelector<HTMLElement>(`${pane} h2`)
    target?.focus()
  }, [view])

  return (
    <div className="@container/chat w-full">
      <div
        ref={grid}
        data-slot="chat-app"
        data-view={view}
        className={cn(
          "group/chat grid h-[50rem] max-h-[100svh] min-h-[32rem] w-full grid-cols-1 grid-rows-[minmax(0,1fr)] gap-6 p-4 pt-10 @3xl/chat:grid-cols-[minmax(16rem,21rem)_minmax(0,1fr)] @3xl/chat:p-6 @3xl/chat:pt-12",
          className
        )}
      >
        <ChatAppConversationList
          conversations={chat.conversations}
          activeId={chat.activeId}
          onSelect={(id) => {
            chat.select(id)
            setView("thread")
          }}
          className="group-data-[view=thread]/chat:@max-3xl/chat:hidden"
        />
        {chat.active ? (
          <ChatAppThread
            key={chat.active.id}
            conversation={chat.active}
            status={chat.status}
            announce={chat.announce}
            onSend={chat.send}
            onStop={chat.stop}
            onBack={() => setView("list")}
            className="group-data-[view=list]/chat:@max-3xl/chat:hidden"
          />
        ) : null}
      </div>
    </div>
  )
}
